def count_seq_descents(catalog) -> int:
    descents = 0
    prev = None
    for rec in catalog:
        seq = rec["seq"]
        if prev is not None and seq < prev:
            descents += 1
        prev = seq
    return descents


def source_start_non_decreasing(catalog) -> bool:
    prev = None
    for rec in catalog:
        ss = rec["source_start"]
        if prev is not None and ss < prev:
            return False
        prev = ss
    return True


def duplicate_preservation(catalog) -> tuple[int, int]:
    groups: dict[tuple, list] = defaultdict(list)
    for rec in catalog:
        raw = rec["raw_text"]
        if raw is not None:
            groups[(rec["record_type"], raw)].append(rec["seq"])
    dup = {k: v for k, v in groups.items() if len(v) > 1}
    return len(dup), sum(len(v) for v in dup.values())


def occupancy_from_catalog(catalog) -> list:
    buckets = [[] for _ in range(LINE_N)]
    for rec in catalog:
        start = rec["source_start"]
        end = rec["source_end"]
        seq = rec["seq"]
        if type(start) is not int or type(end) is not int or type(seq) is not int:
            abort("CATALOG_SPAN_TYPE_COERCION")
        if start < 1 or end > LINE_N or start > end:
            abort("CATALOG_SPAN_OUT_OF_RANGE")
        for line in range(start, end + 1):
            buckets[line - 1].append(seq)
    out = []
    for i, seqs in enumerate(buckets, start=1):
        out.append(OrderedDict([("line", i), ("occupying_seq", seqs)]))
    return out


def occupancy_histogram(occ_index) -> tuple[dict, int]:
    hist = Counter()
    hits = 0
    for item in occ_index:
        n = len(item["occupying_seq"])
        hist[n] += 1
        hits += n
    return dict(hist), hits


def parent_span_lines(line_entries) -> set[int]:
    lines: set[int] = set()
    for le in line_entries:
        if le["reason"] in ("KR-8", "KR-9") and le["model_has_independent_bytes"] is True:
            recon = le["recon_source"]
            if isinstance(recon, str) and recon.startswith("PARENT_SPAN"):
                lines.add(le["line"])
    return lines


def literal_counts(catalog) -> dict:
    def field_counts(field: str) -> tuple[int, int]:
        json_null = 0
        string_null = 0
        for rec in catalog:
            v = rec[field]
            if v is None:
                json_null += 1
            elif v == "NULL" and type(v) is str:
                string_null += 1
        return json_null, string_null

    rk_n, rk_s = field_counts("raw_key")
    rv_n, rv_s = field_counts("raw_value")
    rf_n, rf_s = field_counts("representation_form")
    notes_empty = sum(1 for r in catalog if r["notes"] == "" and type(r["notes"]) is str)
    notes_null = sum(1 for r in catalog if r["notes"] is None)
    cnp_false = sum(1 for r in catalog if r["creates_new_parent"] is False)
    cnp_zero = sum(1 for r in catalog if r["creates_new_parent"] == 0 and type(r["creates_new_parent"]) is int)
    cnp_str = sum(1 for r in catalog if r["creates_new_parent"] == "false")
    return {
        "raw_key_null": rk_n,
        "raw_key_NULL": rk_s,
        "raw_value_null": rv_n,
        "raw_value_NULL": rv_s,
        "representation_form_null": rf_n,
        "representation_form_NULL": rf_s,
