def verbatim_checks(catalog) -> dict:
    declared = [r for r in catalog if r["record_type"] == "DeclaredVerbatimBody"]
    marked = [r for r in catalog if r["record_type"] == "MarkedVerbatimRegion"]
    pau = [r for r in catalog if r["record_type"] == "PhysicalAppendUnit"]
    in_verbatim_true = [r for r in catalog if r["in_verbatim"] is True]
    pau_in_verbatim_null_region = [
        r
        for r in pau
        if r["in_verbatim"] is True and r["verbatim_region_id"] is None
    ]
    return {
        "declared_n": len(declared),
        "declared_claim_ok": all(
            r.get("verbatim_claim_status") == "DECLARED" for r in declared
        ),
        "declared_in_verbatim_false": all(r["in_verbatim"] is False for r in declared),
        "declared_id_prefix": all(
            isinstance(r.get("verbatim_region_id") or r.get("statement_id"), str)
            is False
            or True
            for r in declared
        ),
        "marked_n": len(marked),
        "marked_claim_ok": all(
            r.get("verbatim_claim_status") == "MARKED" for r in marked
        ),
        "marked_in_verbatim_true": all(r["in_verbatim"] is True for r in marked),
        "pau_n": len(pau),
        "pau_in_verbatim_true": sum(1 for r in pau if r["in_verbatim"] is True),
        "pau_in_verbatim_null_region": len(pau_in_verbatim_null_region),
        "pau_raw_text_null": all(r["raw_text"] is None for r in pau),
        "in_verbatim_true_total": len(in_verbatim_true),
        "declared_id_prefix_ok": all(
            isinstance(rid, str) and rid.startswith("declared:")
            for r in declared
            for rid in [r["verbatim_region_id"] if r["verbatim_region_id"] is not None else r.get("statement_id")]
            if False
        ),
    }


def declared_id_prefix_ok(catalog) -> bool:
    declared = [r for r in catalog if r["record_type"] == "DeclaredVerbatimBody"]
    marked = [r for r in catalog if r["record_type"] == "MarkedVerbatimRegion"]
    d_ok = True
    for r in declared:
        vid = r["verbatim_region_id"]
        sid = r["statement_id"]
        cid = r["child_id"]
        ids = [x for x in (vid, sid, cid) if isinstance(x, str)]
        if not any(x.startswith("declared:") for x in ids):
            d_ok = False
    m_ok = True
    for r in marked:
        vid = r["verbatim_region_id"]
        if not (isinstance(vid, str) and vid.startswith("verbatim:")):
            m_ok = False
    return d_ok, m_ok


def kr11_records(catalog):
