def tr005_records(catalog):
    return [r for r in catalog if r["transform_rule"] == "TR-005"]


def walk_values(obj):
    if isinstance(obj, dict):
        for v in obj.values():
            yield from walk_values(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from walk_values(v)
    else:
        yield obj


def contains_h91(rec) -> bool:
    for v in walk_values(rec):
        if isinstance(v, str) and "H91" in v:
            return True
    return False


def validate_payload(step17, *, stage: str) -> dict:
    catalog = step17["CATALOG_RECORDS"]
    lines = step17["LINE_ENTRIES"]
    carriers = step17["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]
    roster = step17["CLOSED_TYPE_ROSTER"]

    if len(catalog) != CATALOG_N:
        abort(f"{stage}:CATALOG_RECORD_COUNT={len(catalog)}")
    if len(lines) != LINE_N:
        abort(f"{stage}:LINE_ENTRY_COUNT={len(lines)}")
    if len(carriers) != CARRIER_N:
        abort(f"{stage}:CARRIER_COUNT={len(carriers)}")
    if len(roster) != ROSTER_N:
        abort(f"{stage}:CLOSED_TYPE_ROSTER_COUNT={len(roster)}")

    for rec in catalog:
        if len(rec.keys()) != CATALOG_KEYS_N:
            abort(f"{stage}:CATALOG_KEY_COUNT_DRIFT")
        if rec["authority_status"] != "NONE":
            abort(f"{stage}:AUTHORITY_STATUS_NOT_NONE")

    types = {r["record_type"] for r in catalog}
    roster_types = [r["record_type"] for r in roster]
    if len(roster_types) != ROSTER_N:
        abort(f"{stage}:ROSTER_TYPE_COUNT")
    if len(set(roster_types)) != ROSTER_N:
        abort(f"{stage}:ROSTER_TYPE_DEDUP")
    extra = types - set(roster_types)
    if extra:
        abort(f"{stage}:38TH_RECORD_TYPE")

    descents = count_seq_descents(catalog)
    if descents != SEQ_DESCENTS_N:
        abort(f"{stage}:SEQ_DESCENTS={descents}")
    if not source_start_non_decreasing(catalog):
        abort(f"{stage}:SOURCE_START_DECREASING")

    dg, dr = duplicate_preservation(catalog)
    if dg != DUP_GROUPS_N or dr != DUP_RECORDS_N:
        abort(f"{stage}:DUPLICATE_DRIFT groups={dg} records={dr}")

    snv = [r for r in catalog if r["record_type"] == "ShaNamedValue"]
    if len(snv) != SNV_N:
        abort(f"{stage}:SHA_NAMED_VALUE_RECORDS={len(snv)}")
    distinct_sha = {r["sha_value_raw"] for r in snv}
    if len(distinct_sha) != SNV_DISTINCT_N:
        abort(f"{stage}:SHA_NAMED_VALUE_DISTINCT_VALUES={len(distinct_sha)}")

    if [le["line"] for le in lines] != list(range(1, LINE_N + 1)):
        abort(f"{stage}:LINE_ENTRIES_NOT_ASCENDING_1_TO_N")

    psl = parent_span_lines(lines)
    if len(psl) != PARENT_SPAN_N:
        abort(f"{stage}:PARENT_SPAN_KR8_KR9_COUNT={len(psl)}")
    carrier_lines = {c["line"] for c in carriers}
    inter = carrier_lines & psl
    if inter:
        abort(f"{stage}:CARRIER_PARENT_SPAN_INTERSECTION_COUNT={len(inter)}")

    for c in carriers:
        if list(c.keys()) != list(CARRIER_KEYS):
            abort(f"{stage}:CARRIER_KEYS_DRIFT")
        if "record_type" in c or "payload" in c:
            abort(f"{stage}:CARRIER_ENTITY")
        if c["mechanism"] != "SOURCE_FILE_IDENTITY_COPY":
            abort(f"{stage}:CARRIER_MECHANISM")
        if c["synthesis"] is not False or c["normalization"] is not False:
            abort(f"{stage}:CARRIER_SYNTHESIS_OR_NORMALIZATION")
        if c["independent_model_bytes"] is not False:
            abort(f"{stage}:CARRIER_INDEPENDENT_MODEL_BYTES")
    kr9 = sum(1 for c in carriers if c["keeping_rule"] == "KR-9")
    kr8 = sum(1 for c in carriers if c["keeping_rule"] == "KR-8")
    if kr9 != 4243 or kr8 != 613:
        abort(f"{stage}:CARRIER_KR_COUNTS kr9={kr9} kr8={kr8}")

    occ = occupancy_from_catalog(catalog)
    hist, hits = occupancy_histogram(occ)
    if hist != OCC_HIST:
        abort(f"{stage}:OCCUPANCY_HISTOGRAM_DRIFT {hist}")
    if hits != OCC_HITS:
        abort(f"{stage}:OCCUPANCY_TOTAL_HITS={hits}")

    step17_occ = step17.get("STRUCTURE_CHROME", {}).get("OCCUPANCY_PER_SOURCE_LINE")
    if step17_occ is not None:
        if len(step17_occ) != LINE_N:
            abort(f"{stage}:STEP17_OCCUPANCY_LEN")
        for a, b in zip(occ, step17_occ):
            if a["line"] != b["line"] or a["occupying_seq"] != b["occupying_seq"]:
                abort(f"{stage}:OCCUPANCY_RECOMPUTE_MISMATCH_VS_STEP17")

    lit = literal_counts(catalog)
    if lit["raw_key_null"] != 11006 or lit["raw_key_NULL"] != 14:
        abort(f"{stage}:RAW_KEY_LITERAL {lit}")
    if lit["raw_value_null"] != 11006 or lit["raw_value_NULL"] != 18:
        abort(f"{stage}:RAW_VALUE_LITERAL {lit}")
    if lit["representation_form_null"] != 23130 or lit["representation_form_NULL"] != 14:
        abort(f"{stage}:REPRESENTATION_FORM_LITERAL {lit}")
    if lit["notes_empty"] != 23841 or lit["notes_null"] != 0:
        abort(f"{stage}:NOTES_LITERAL {lit}")
    if lit["creates_new_parent_false"] != CATALOG_N:
        abort(f"{stage}:CREATES_NEW_PARENT_NOT_ALL_FALSE")
    if lit["creates_new_parent_int0"] != 0 or lit["creates_new_parent_str"] != 0:
        abort(f"{stage}:CREATES_NEW_PARENT_COERCION")

    epi = epistemic_counts(catalog)
    if epi["authority_none"] != CATALOG_N:
        abort(f"{stage}:AUTHORITY_STATUS_COUNT")
    if epi["epistemic_null"] != CATALOG_N:
        abort(f"{stage}:EPISTEMIC_STATUS_NOT_NULL")
    if epi["currentness_null"] != CATALOG_N:
        abort(f"{stage}:CURRENTNESS_NOT_NULL")
    if epi["adjudication_null"] != CATALOG_N:
        abort(f"{stage}:ADJUDICATION_NOT_NULL")
    if epi["provenance_null"] != CATALOG_N:
        abort(f"{stage}:PROVENANCE_FORM_NOT_NULL")
    if epi["classification_unresolved"] != UNRESOLVED_N:
        abort(f"{stage}:UNRESOLVED_COUNT={epi['classification_unresolved']}")
    if epi["classification_null"] != 23942:
        abort(f"{stage}:CLASSIFICATION_NULL={epi['classification_null']}")
    if epi["navigation"] != NAV_N:
        abort(f"{stage}:NAVIGATION_COUNT={epi['navigation']}")
    if epi["unresolved_status"] != UNRESOLVED_N:
        abort(f"{stage}:UNRESOLVED_STATUS_COUNT")

    kr11 = kr11_records(catalog)
    if len(kr11) != KR11_N:
        abort(f"{stage}:KR11_COUNT={len(kr11)}")
    for r in kr11:
        if r["raw_key"] != "NULL" or r["raw_value"] != "NULL" or r["representation_form"] != "NULL":
            abort(f"{stage}:KR11_NULL_STRING_DRIFT")
        if type(r["raw_key"]) is not str:
            abort(f"{stage}:KR11_TYPE_COERCION")
        if contains_h91(r):
            abort(f"{stage}:H91_KR11_FUSION")

    tr005 = tr005_records(catalog)
    if len(tr005) != TR005_N:
        abort(f"{stage}:TR005_COUNT={len(tr005)}")
    for r in tr005:
        if r["raw_key"] is not None or r["raw_value"] is not None:
            abort(f"{stage}:TR005_NOT_JSON_NULL")

    fence_null = sum(
        1 for r in catalog if r["in_fence"] is True and r["fence_id"] is None
    )
    if fence_null != IN_FENCE_NULL_N:
        abort(f"{stage}:IN_FENCE_TRUE_AND_FENCE_ID_NULL={fence_null}")

    pau = [r for r in catalog if r["record_type"] == "PhysicalAppendUnit"]
    if len(pau) != PAU_N:
        abort(f"{stage}:PAU={len(pau)}")
    pau_iv_null = sum(
        1 for r in pau if r["in_verbatim"] is True and r["verbatim_region_id"] is None
    )
    if pau_iv_null != PAU_IN_VERBATIM_NULL_REGION_N:
        abort(f"{stage}:PAU_IN_VERBATIM_TRUE_AND_REGION_NULL={pau_iv_null}")
    if any(r["raw_text"] is not None for r in pau):
        abort(f"{stage}:PAU_RAW_TEXT_NOT_NULL")

    declared = [r for r in catalog if r["record_type"] == "DeclaredVerbatimBody"]
    marked = [r for r in catalog if r["record_type"] == "MarkedVerbatimRegion"]
    if len(declared) != 2:
        abort(f"{stage}:DECLARED_VERBATIM_BODY={len(declared)}")
    if len(marked) != 5:
        abort(f"{stage}:MARKED_VERBATIM_REGION={len(marked)}")
    for r in declared:
        if r["verbatim_claim_status"] != "DECLARED" or r["in_verbatim"] is not False:
            abort(f"{stage}:DECLARED_VERBATIM_CONTRACT")
        ids = [x for x in (r["verbatim_region_id"], r["statement_id"], r["child_id"]) if isinstance(x, str)]
        if not any(x.startswith("declared:") for x in ids):
            abort(f"{stage}:DECLARED_ID_PREFIX")
    for r in marked:
        if r["verbatim_claim_status"] != "MARKED" or r["in_verbatim"] is not True:
            abort(f"{stage}:MARKED_VERBATIM_CONTRACT")
        if not (isinstance(r["verbatim_region_id"], str) and r["verbatim_region_id"].startswith("verbatim:")):
            abort(f"{stage}:MARKED_ID_PREFIX")
    if sum(1 for r in catalog if r["in_verbatim"] is True) != 10:
        abort(f"{stage}:IN_VERBATIM_TRUE_TOTAL")

    indep = [le for le in lines if le["model_has_independent_bytes"] is True]
    if len(indep) != INDEP_BYTES_N:
        abort(f"{stage}:INDEPENDENT_BYTES={len(indep)}")
    occ_by_line = {item["line"]: item["occupying_seq"] for item in occ}
    pau_starts = {r["source_start"] for r in pau}
    indep_occ1 = [le["line"] for le in indep if len(occ_by_line[le["line"]]) == 1]
    if len(indep_occ1) != INDEP_OCC1_PAU_START_N:
        abort(f"{stage}:INDEP_OCC1={len(indep_occ1)}")
    if any(line not in pau_starts for line in indep_occ1):
        abort(f"{stage}:INDEP_OCC1_NOT_PAU_START")
    if INDEP_BYTES_N - len(indep_occ1) != INDEP_OCC_GE2_N:
        abort(f"{stage}:INDEP_OCC_GE2")

    for le in lines:
        if "reason" not in le:
            abort(f"{stage}:LINE_MISSING_REASON")

    return {
        "occ": occ,
        "hist": hist,
        "hits": hits,
        "descents": descents,
        "dup_groups": dg,
        "dup_records": dr,
        "parent_span": len(psl),
        "carrier_parent_inter": 0,
        "kr11": len(kr11),
        "tr005": len(tr005),
        "nav": epi["navigation"],
        "unresolved": epi["classification_unresolved"],
        "fence_null": fence_null,
        "pau_iv_null": pau_iv_null,
        "snv": len(snv),
        "snv_distinct": len(distinct_sha),
        "lit": lit,
        "epi": epi,
    }


