def validate_output_graph(out, step17, stats) -> None:
    keys = list(out.keys())
    expected_keys = [
        "PRODUCT_A_ENVELOPE",
        "PREVIEW_ENVELOPE",
        "CANDIDATE_ENVELOPE",
        "CLOSED_TYPE_ROSTER",
        "CATALOG_RECORDS",
        "LINE_ENTRIES",
        "KR8_KR9_SOURCE_BYTE_CARRIER_INDEX",
        "OCCUPANCY_INDEX",
    ]
    if keys != expected_keys:
        abort(f"ROOT_KEY_ORDER={keys}")

    env = out["PRODUCT_A_ENVELOPE"]
    if env["ARTIFACT_AUTHORITY"] != "NONE":
        abort("ARTIFACT_AUTHORITY_NOT_NONE")
    if env["TARGET_AUTHORITY"] != "NONE":
        abort("TARGET_AUTHORITY_NOT_NONE")
    if env["IS_TARGET"] is not False:
        abort("IS_TARGET_NOT_FALSE")
    if env["IS_SSOT"] is not False:
        abort("IS_SSOT_NOT_FALSE")
    if env["TARGET_REPLACEMENT"] is not False:
        abort("TARGET_REPLACEMENT_NOT_FALSE")
    if env["CANONICALIZATION"] is not False:
        abort("CANONICALIZATION_NOT_FALSE")
    if env["PRODUCT_CLASS"] != "PRODUCT_A":
        abort("PRODUCT_CLASS_NOT_PRODUCT_A")
    if env["MASTER_RUNBOOK_REMAINS_SOLE_SSOT"] is not True:
        abort("MASTER_NOT_SOLE_SSOT")
    if env["STEP16_CONSUMED"] is not False:
        abort("STEP16_CONSUMED_TRUE")
    if env["PRODUCT_B_EXECUTED"] is not False or env["PRODUCT_C_EXECUTED"] is not False:
        abort("PRODUCT_B_OR_C_EXECUTED")
    if env["U1_STATUS"] != "OPEN_UNCHANGED" or env["U2_STATUS"] != "OPEN_UNCHANGED":
        abort("U1_U2_NOT_OPEN_UNCHANGED")
    if "H91" in json.dumps(env, ensure_ascii=False):
        abort("H91_IN_PRODUCT_A_ENVELOPE")

    if out["PREVIEW_ENVELOPE"] != step17["PREVIEW_ENVELOPE"]:
        abort("PREVIEW_ENVELOPE_MUTATED")
    if out["CANDIDATE_ENVELOPE"] != step17["CANDIDATE_ENVELOPE"]:
        abort("CANDIDATE_ENVELOPE_MUTATED")
    if out["CLOSED_TYPE_ROSTER"] != step17["CLOSED_TYPE_ROSTER"]:
        abort("ROSTER_NOT_IDENTICAL")
    if out["LINE_ENTRIES"] != step17["LINE_ENTRIES"]:
        abort("LINE_ENTRIES_NOT_IDENTICAL")
    if out["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"] != step17["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]:
        abort("CARRIERS_NOT_IDENTICAL")
    if len(out["CATALOG_RECORDS"]) != CATALOG_N:
        abort("OUTPUT_CATALOG_COUNT")
    for i, rec in enumerate(out["CATALOG_RECORDS"]):
        if rec != step17["CATALOG_RECORDS"][i]:
            abort(f"CATALOG_OBJECT_IDENTITY_FAIL i={i}")

    if len(out["OCCUPANCY_INDEX"]) != LINE_N:
        abort("OCCUPANCY_INDEX_LEN")
    if [x["line"] for x in out["OCCUPANCY_INDEX"]] != list(range(1, LINE_N + 1)):
        abort("OCCUPANCY_INDEX_LINE_ORDER")
    hist, hits = occupancy_histogram(out["OCCUPANCY_INDEX"])
    if hist != OCC_HIST or hits != OCC_HITS:
        abort("OUTPUT_OCCUPANCY_DRIFT")
    if out["OCCUPANCY_INDEX"] != stats["occ"]:
        abort("OCCUPANCY_INDEX_NOT_RECOMPUTED_IDENTITY")

    wrapped = OrderedDict(
        [
            ("CLOSED_TYPE_ROSTER", out["CLOSED_TYPE_ROSTER"]),
            ("CATALOG_RECORDS", out["CATALOG_RECORDS"]),
            ("LINE_ENTRIES", out["LINE_ENTRIES"]),
            ("KR8_KR9_SOURCE_BYTE_CARRIER_INDEX", out["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]),
            ("STRUCTURE_CHROME", step17["STRUCTURE_CHROME"]),
            ("PREVIEW_ENVELOPE", out["PREVIEW_ENVELOPE"]),
        ]
