        OrderedDict(
            [
                ("CLOSED_TYPE_ROSTER", out["CLOSED_TYPE_ROSTER"]),
                ("CATALOG_RECORDS", out["CATALOG_RECORDS"]),
                ("LINE_ENTRIES", out["LINE_ENTRIES"]),
                ("KR8_KR9_SOURCE_BYTE_CARRIER_INDEX", out["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]),
                ("STRUCTURE_CHROME", step17["STRUCTURE_CHROME"]),
                ("PREVIEW_ENVELOPE", out["PREVIEW_ENVELOPE"]),
            ]
        ),
        stage="OUTPUT_GRAPH",
    )
    del wrapped


def assert_bindings(snapshot: dict, *, stage: str) -> None:
    mapping = {
        "STEP17": ("STEP17_SHA256", "STEP17_SIZE_BYTES"),
        "PREVIEW": ("PREVIEW_SHA256", None),
        "STEP15": ("STEP15_SHA256", None),
        "STEP9": ("STEP9_SHA256", None),
        "TARGET": ("TARGET_SHA256", None),
        "MASTER": ("MASTER_SHA256", None),
        "MAP": ("MAP_SHA256", None),
    }
    for name, (sha_key, size_key) in mapping.items():
        if snapshot[name]["sha256"] != EXPECTED[sha_key]:
            abort("BOUND_INPUT_IDENTITY_MISMATCH")
        if size_key is not None and snapshot[name]["size"] != EXPECTED[size_key]:
            abort("BOUND_INPUT_IDENTITY_MISMATCH")
    if snapshot["HEAD"] != EXPECTED["HEAD"]:
        abort("BOUND_INPUT_IDENTITY_MISMATCH")
    if snapshot["origin_main"] != EXPECTED["HEAD"]:
        abort("BOUND_INPUT_IDENTITY_MISMATCH")


def snapshot_now() -> dict:
    snap = {
        "STEP17": file_stat(STEP17_PATH),
        "PREVIEW": file_stat(PREVIEW_PATH),
        "STEP15": file_stat(STEP15_PATH),
        "STEP9": file_stat(STEP9_PATH),
        "TARGET": file_stat(TARGET_PATH),
        "MASTER": file_stat(MASTER_PATH),
        "MAP": file_stat(MAP_PATH),
        "HEAD": git_head(),
        "origin_main": subprocess.check_output(
            ["git", "rev-parse", "origin/main"], cwd=REPO, text=True
        ).strip(),
        "porcelain": git_porcelain(),
    }
    return snap


def snapshots_equal(a: dict, b: dict) -> bool:
    keys = ["STEP17", "PREVIEW", "STEP15", "STEP9", "TARGET", "MASTER", "MAP"]
    for k in keys:
        if a[k]["sha256"] != b[k]["sha256"] or a[k]["size"] != b[k]["size"] or a[k]["ino"] != b[k]["ino"]:
            return False
    if a["HEAD"] != b["HEAD"] or a["origin_main"] != b["origin_main"]:
        return False
    if a["porcelain"] != b["porcelain"]:
        return False
    return True


def emit_abort(reason: str) -> None:
    print("STEP21_EXECUTION_STATUS=ABORT")
    print("STEP21_VALIDATION=FAIL")
    print(f"ABORT_REASON={reason}")
    print("FINAL_ARTIFACT_CREATED=false")
    print("TARGET_MUTATED=false")
    print("BOUND_INPUTS_MUTATED=false")
    print("REPOSITORY_MUTATED=false")


def main() -> int:
    tmp_path = None
    try:
        if os.path.exists(DEST):
            abort("STEP21_DESTINATION_EXISTS")

        snapshot_before = snapshot_now()
        assert_bindings(snapshot_before, stage="PREWRITE")
        if snapshot_before["porcelain"] != "":
            abort("REPOSITORY_PORCELAIN_NOT_CLEAN")

        print("LOAD_STEP17", flush=True)
        with open(STEP17_PATH, "r", encoding="utf-8") as f:
            step17 = json.load(f, object_pairs_hook=OrderedDict)
        if sha256_file(STEP17_PATH) != EXPECTED["STEP17_SHA256"]:
            abort("BOUND_INPUT_IDENTITY_MISMATCH")

        required_layers = [
            "PREVIEW_ENVELOPE",
            "CANDIDATE_ENVELOPE",
            "CLOSED_TYPE_ROSTER",
            "CATALOG_RECORDS",
            "LINE_ENTRIES",
            "KR8_KR9_SOURCE_BYTE_CARRIER_INDEX",
        ]
        for k in required_layers:
            if k not in step17:
                abort("PAYLOAD_SOURCE_NOT_STEP17_FIVE_LAYER_MODEL")

        print("PREWRITE_VALIDATE", flush=True)
        stats = validate_payload(step17, stage="PREWRITE")

        print("BUILD_PRODUCT_A", flush=True)
        out = build_product_a(step17, snapshot_before, stats["occ"])
        validate_output_graph(out, step17, stats)

        print("IN_MEMORY_RENDER", flush=True)
        text1 = dumps(out) + "\n"
        loaded1 = loads(text1)
        text2 = dumps(loaded1) + "\n"
        loaded2 = loads(text2)
        if loaded1 != loaded2:
            abort("SECOND_IN_MEMORY_RENDER_NOT_TYPED_IDENTICAL")
        if text1 != text2:
            abort("SECOND_IN_MEMORY_RENDER_BYTES_DRIFT")
        if loaded1["CATALOG_RECORDS"] != step17["CATALOG_RECORDS"]:
            abort("RENDER_CATALOG_NOT_IDENTICAL")
        if loaded1["LINE_ENTRIES"] != step17["LINE_ENTRIES"]:
            abort("RENDER_LINE_ENTRIES_NOT_IDENTICAL")
        if loaded1["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"] != step17["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]:
            abort("RENDER_CARRIERS_NOT_IDENTICAL")
        if loaded1["CLOSED_TYPE_ROSTER"] != step17["CLOSED_TYPE_ROSTER"]:
            abort("RENDER_ROSTER_NOT_IDENTICAL")

        if os.path.exists(DEST):
            abort("STEP21_DESTINATION_EXISTS")

        print("ATOMIC_TEMP_WRITE", flush=True)
        fd, tmp_path = tempfile.mkstemp(
            prefix=".peak_trade_step21_",
            suffix=".json.tmp",
            dir=DEST_DIR,
        )
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as wf:
            wf.write(text1)
            wf.flush()
            os.fsync(wf.fileno())

        print("POSTWRITE_REREAD_TEMP", flush=True)
        with open(tmp_path, "r", encoding="utf-8") as rf:
            reread_text = rf.read()
        if reread_text != text1:
            abort("TEMP_REREAD_BYTES_MISMATCH")
        reread = loads(reread_text)
        if reread != loaded1:
            abort("TEMP_REREAD_TYPED_MISMATCH")

        reread_stats_wrapper = OrderedDict(
            [
                ("CLOSED_TYPE_ROSTER", reread["CLOSED_TYPE_ROSTER"]),
                ("CATALOG_RECORDS", reread["CATALOG_RECORDS"]),
                ("LINE_ENTRIES", reread["LINE_ENTRIES"]),
                ("KR8_KR9_SOURCE_BYTE_CARRIER_INDEX", reread["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]),
                ("STRUCTURE_CHROME", step17["STRUCTURE_CHROME"]),
                ("PREVIEW_ENVELOPE", reread["PREVIEW_ENVELOPE"]),
            ]
        )
        reread_payload_stats = validate_payload(reread_stats_wrapper, stage="POSTWRITE")
        if reread["CATALOG_RECORDS"] != step17["CATALOG_RECORDS"]:
            abort("POSTWRITE_CATALOG_OBJECT_IDENTITY_FAIL")
        if reread["LINE_ENTRIES"] != step17["LINE_ENTRIES"]:
            abort("POSTWRITE_LINE_ENTRY_IDENTITY_FAIL")
        if reread["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"] != step17["KR8_KR9_SOURCE_BYTE_CARRIER_INDEX"]:
            abort("POSTWRITE_CARRIER_IDENTITY_FAIL")
        if reread["CLOSED_TYPE_ROSTER"] != step17["CLOSED_TYPE_ROSTER"]:
            abort("POSTWRITE_ROSTER_IDENTITY_FAIL")
        if reread["PREVIEW_ENVELOPE"] != step17["PREVIEW_ENVELOPE"]:
            abort("POSTWRITE_PREVIEW_ENVELOPE_DRIFT")
        if reread["CANDIDATE_ENVELOPE"] != step17["CANDIDATE_ENVELOPE"]:
            abort("POSTWRITE_CANDIDATE_ENVELOPE_DRIFT")
        if reread["OCCUPANCY_INDEX"] != stats["occ"]:
            abort("POSTWRITE_OCCUPANCY_DRIFT")
        if reread["PRODUCT_A_ENVELOPE"]["TARGET_AUTHORITY"] != "NONE":
            abort("POSTWRITE_TARGET_AUTHORITY")
        if reread["PRODUCT_A_ENVELOPE"]["IS_SSOT"] is not False:
            abort("POSTWRITE_IS_SSOT")
        if reread["PRODUCT_A_ENVELOPE"]["ARTIFACT_AUTHORITY"] != "NONE":
            abort("POSTWRITE_ARTIFACT_AUTHORITY")
        for rec in kr11_records(reread["CATALOG_RECORDS"]):
            if contains_h91(rec):
                abort("POSTWRITE_H91_KR11_FUSION")

        tmp_sha = sha256_file(tmp_path)
        tmp_size = os.path.getsize(tmp_path)
        if tmp_sha == EXPECTED["TARGET_SHA256"]:
            abort("OUTPUT_SHA_EQUALS_TARGET")
        if tmp_sha == EXPECTED["STEP9_SHA256"]:
            abort("OUTPUT_SHA_EQUALS_STEP9")
        if tmp_sha == EXPECTED["PREVIEW_SHA256"]:
            abort("OUTPUT_SHA_EQUALS_PREVIEW")
        if tmp_sha == EXPECTED["STEP17_SHA256"]:
            # allowed to differ; PRODUCT_A is a new render. Equality would be unexpected.
            abort("OUTPUT_SHA_EQUALS_STEP17_UNEXPECTED")

        snapshot_mid = snapshot_now()
        if not snapshots_equal(snapshot_before, snapshot_mid):
            abort("BOUND_INPUTS_MUTATED_BEFORE_FINALIZE")
        if os.path.exists(DEST):
            abort("STEP21_DESTINATION_EXISTS")

        print("ATOMIC_RENAME", flush=True)
        os.replace(tmp_path, DEST)
        tmp_path = None
        dirfd = os.open(DEST_DIR, os.O_RDONLY)
        try:
            os.fsync(dirfd)
        finally:
            os.close(dirfd)

        final_sha = sha256_file(DEST)
        final_size = os.path.getsize(DEST)
        if final_sha != tmp_sha or final_size != tmp_size:
            abort("FINAL_SHA_MISMATCH_VS_TEMP")

        snapshot_after = snapshot_now()
        if not snapshots_equal(snapshot_before, snapshot_after):
            abort("BOUND_INPUTS_MUTATED_AFTER_WRITE")
        if snapshot_after["porcelain"] != "":
            abort("REPOSITORY_MUTATED")

        env = reread["PRODUCT_A_ENVELOPE"]
        print("STEP21_EXECUTION_STATUS=PASS")
        print("STEP21_VALIDATION=PASS")
        print("PRODUCT_CLASS=PRODUCT_A")
        print(f"ARTIFACT_PATH={DEST}")
        print(f"ARTIFACT_SHA256={final_sha}")
        print(f"ARTIFACT_SIZE_BYTES={final_size}")
        print("ARTIFACT_AUTHORITY=NONE")
        print("TARGET_AUTHORITY=NONE")
        print("IS_TARGET=false")
        print("IS_SSOT=false")
        print("TARGET_REPLACEMENT=false")
        print("CANONICALIZATION=false")
        print("MASTER_RUNBOOK_REMAINS_SOLE_SSOT=true")
        print("BOUND_INPUT_IDENTITY_VALIDATION=PASS")
        print("STEP17_IDENTITY_VALIDATION=PASS")
        print("PAYLOAD_SOURCE_VALIDATION=PASS")
        print(f"CATALOG_RECORD_COUNT={CATALOG_N}")
        print(f"LINE_ENTRY_COUNT={LINE_N}")
        print(f"CARRIER_COUNT={CARRIER_N}")
        print(f"CLOSED_TYPE_ROSTER_COUNT={ROSTER_N}")
        print(f"UNRESOLVED_COUNT={UNRESOLVED_N}")
        print(f"SEQ_DESCENTS={SEQ_DESCENTS_N}")
        print("SOURCE_START_NON_DECREASING=true")
        print(f"DUPLICATE_GROUPS={DUP_GROUPS_N}")
        print(f"RECORDS_IN_DUPLICATE_GROUPS={DUP_RECORDS_N}")
        print(f"SHA_NAMED_VALUE_RECORDS={SNV_N}")
